    await db.query('UPDATE "InternalModel2Run" SET status=\'interrupted\',reason=$3,"updatedAt"=now() WHERE id=$1 AND token=$2 AND status=\'running\'', [id, claimed.token, reason.slice(0, 500)]);
  });
