      await db.query(`UPDATE "InternalModel2Run" SET status=CASE WHEN "cancelRequested" OR NOT EXISTS (SELECT 1 FROM "InternalModel2Grant" WHERE "userId"="ownerId") THEN 'cancelled' ELSE 'completed' END,"updatedAt"=now()
