}
export function createComputeRuntime(authored: ComputeInput, compose?: (kernel: EventKernel, deliver: Deliver, controls: { pause(id: string, value: boolean): void; observe(id: string): unknown; abortOwned(id: string): void }) => ComputeComposition, resourceFactory?: ResourceFactory) {
  validateComputeInput(authored);
